def can_win(s, a, b, is_alice_turn):
    """
    Determine if the current player can win given string s, move lengths a and b,
    and whether it's Alice's turn (True) or Bob's turn (False).
    """
    # Check if current player can make a move
    if is_alice_turn:
        # Alice needs to find a substring of length a consisting only of '.'
        for i in range(len(s) - a + 1):
            if all(s[j] == '.' for j in range(i, i + a)):
                # Try this move and see if Bob cannot win
                new_s = s[:i] + ('X' * a) + s[i + a:]
                if not can_win(new_s, a, b, False):
                    return True
        return False  # No winning move
    else:
        # Bob needs to find a substring of length b consisting only of '.'
        for i in range(len(s) - b + 1):
            if all(s[j] == '.' for j in range(i, i + b)):
                # Try this move and see if Alice cannot win
                new_s = s[:i] + ('X' * b) + s[i + b:]
                if not can_win(new_s, a, b, True):
                    return True
        return False  # No winning move

q = int(input())
for _ in range(q):
    a, b = map(int, input().split())
    s = input().strip()

    # Alice goes first
    if can_win(s, a, b, True):
        print("YES")
    else:
        print("NO")
