def rotate(piece, clockwise=1):
    """Rotate a piece clockwise by 90 degrees."""
    if clockwise % 4 == 0:
        return piece
    # Rotate 90 degrees clockwise
    return [list(row) for row in zip(*piece[::-1])]

def get_all_rotations(piece):
    """Get all rotations of a piece (including original)."""
    rotations = []
    current = piece
    for _ in range(4):
        rotations.append(current)
        current = rotate(current)
    return rotations

def is_good_puzzle(A, B, picture, X, Y):
    """Check if the puzzle with piece size X×Y is good."""
    # Divide the picture into pieces
    pieces = []
    for i in range(0, A, X):
        for j in range(0, B, Y):
            piece = []
            for di in range(X):
                row = []
                for dj in range(Y):
                    row.append(picture[i+di][j+dj])
                piece.append(row)
            pieces.append(piece)

    # Check all pairs
    for i in range(len(pieces)):
        for j in range(i+1, len(pieces)):
            # Check if any rotation of piece i matches piece j
            if any(all(row1 == row2 for row1, row2 in zip(rot_i, rot_j)) 
                   for rot_i in get_all_rotations(pieces[i]) 
                   for rot_j in get_all_rotations(pieces[j])):
                return False
    return True

def solve():
    A, B = map(int, input().split())
    picture = []
    for _ in range(A):
        picture.append(input().strip())

    good_puzzles = 0
    min_area = float('inf')
    min_x = float('inf')

    # Find all divisors
    def get_divisors(n):
        divisors = set()
        for i in range(1, n + 1):
            if n % i == 0:
                divisors.add(i)
                divisors.add(n // i)
        return sorted(divisors)

    divisors_A = get_divisors(A)
    divisors_B = get_divisors(B)

    for X in divisors_A:
        for Y in divisors_B:
            if is_good_puzzle(A, B, picture, X, Y):
                good_puzzles += 1
                area = X * Y
                if area < min_area or (area == min_area and X < min_x):
                    min_area = area
                    min_x = X

    print(good_puzzles)
    print(min_x, min_area)

solve()
