def main():
    # Read first line
    first_line = sys.stdin.readline()
    if not first_line:
        return

    n, m, k = map(int, first_line.split())

    MOD = 1000000007

    # Initialize transition matrix
    trans = [[1] * m for _ in range(m)]

    # Read forbidden pairs
    for _ in range(k):
        line = sys.stdin.readline().strip()
        if not line:
            continue
        c1, c2 = line[0], line[1]

        # Convert characters to indices
        if 'a' <= c1 <= 'z':
            i = ord(c1) - ord('a') + 1
        else:
            i = ord(c1) - ord('A') + 27

        if 'a' <= c2 <= 'z':
            j = ord(c2) - ord('a') + 1
        else:
            j = ord(c2) - ord('A') + 27

        # Ensure we don't go out of bounds
