import sys

def can_place(bottles, h, k):
    """Check if we can place first k bottles"""
    bottles = sorted(bottles[:k])  # Sort by height

    # We have two columns, both initially have height h
    col1 = h
    col2 = h

    for height in bottles:
        # Try to place the bottle
        if col1 >= height:
            col1 -= height
        elif col2 >= height:
            col2 -= height
        else:
            # Can't place this bottle
            return False
    return True

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    h = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Binary search on k
    low = 1
    high = n
    answer = 1

    while low <= high:
        mid = (low + high) // 2
        if can_place(a, h, mid):
            answer = mid
            low = mid + 1
        else:
            high = mid - 1

    print(answer)

if __name__ == "__main__":
