import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse input
    h = int(data[0])
    w = int(data[1])
    grid = []
    idx = 2

    for i in range(h):
        row = data[idx]
        grid.append(row)
        idx += 1

    # Initialize DP table
    dp = [[0] * w for _ in range(h)]

    # Starting position (0,0)
    if grid[0][0] == '*':
        dp[0][0] = 1
    else:
        dp[0][0] = 0

    # Fill DP table
    for i in range(h):
        for j in range(w):
            if i == 0 and j == 0:
                continue

            # Only move right or down
            max_prev = 0
            if i > 0:
                max_prev = max(max_prev, dp[i-1][j])
            if j > 0:
                max_prev = max(max_prev, dp[i][j-1])

            if grid[i][j] == '*':
                dp[i][j] = max_prev + 1
            else:
                dp[i][j] = max_prev

    print(dp[-1][-1])

