def count_distinct_sums(n):
    """Count how many distinct sums can be formed using exactly n digits from {1, 5, 10, 50}"""

    # Possible values of each digit
    values = [1, 5, 10, 50]

    # Use dynamic programming to count distinct sums
    # dp[i] = set of sums that can be formed with exactly i digits
    dp = [set() for _ in range(n + 1)]
    dp[0].add(0)

    for count in range(n):
        for value in values:
            for s in dp[count]:
                dp[count + 1].add(s + value)

    # Return the number of distinct sums with exactly n digits
    return len(dp[n])

