def can_reach(target, a, w, m):
    """Check if we can make all flowers at least target height"""

    # Calculate how many units each flower needs
    needs = [max(0, target - a[i]) for i in range(len(a))]

    # Count how many watering segments we need
    segments = 0

    for i in range(len(needs)):
        if needs[i] > 0:
            segments += 1

            # We can only water w contiguous flowers at a time
            # So after watering, we need to skip the next (w-1) flowers
            for j in range(i + 1, min(i + w, len(needs))):
                needs[j] -= 1
                if needs[j] == 0:
                    break

    return segments <= m

n, m, w = map(int, input().split())
a = list(map(int, input().split()))

# Binary search for the maximum possible height
low = min(a)
high = low + m

while low < high:
    mid = (low + high + 1) // 2
    if can_reach(mid, a, w, m):
        low = mid
    else:
        high = mid - 1

print(low)
