import sys

def is_lucky(n):
    while n > 0:
        if n % 10 not in {4, 7}:
            return False
        n //= 10
    return True

def count_lucky_in_interval(a, b):
    # Count lucky numbers in [a, b]
    count = 0
    for n in range(max(1, a), b + 1):
        if is_lucky(n):
            count += 1
    return count

pl, pr, vl, vr, k = map(int, sys.stdin.read().split())

