for p in range(pl, pr + 1):
    for v in range(vl, vr + 1):
        a = min(p, v)
        b = max(p, v)
        lucky_count = count_lucky_in_interval(a, b)
        if lucky_count == k:
            count += 1

probability = count / total_pairs
print(probability)
