    n = int(input())
    a = list(map(int, input().split()))
    q = int(input())
    queries = [int(input()) for _ in range(q)]

    # Function to get the parity vector of a number
    def get_parity(x):
        # Return the tuple of primes with odd exponent
        v = []
        for p in range(2, int(x**0.5) + 1):
            cnt = 0
            while x % p == 0:
                cnt += 1
                x //= p
            if cnt % 2 == 1:
                v.append(p)
        if x > 1:
            v.append(x)
        return tuple(v)

    # Group numbers by their parity vector
    from collections import defaultdict
    groups = defaultdict(list)
    for num in a:
        par = get_parity(num)
        groups[par].append(num)

    # After each second, each element becomes the product of all elements in its group
    # The new group size is the same as the original size (each element replaces itself)
    # The parity vector of the product depends on the number of elements in the group

    # Let's compute the parity vectors and their sizes
    par_sizes = {}
    for par, nums in groups.items():
        par_sizes[par] = len(nums)

    # Function to compute beauty after t seconds
    def compute_beauty(t):
        # After 0 seconds, the beauty is the size of the largest group
        if t == 0:
            return max(par_sizes.values())

        # For t >= 1, the parity vector of each group either stays the same (if size odd) or becomes 0 (if size even)
        # Then we need to count how many elements have each parity vector after t seconds

        # After 1 second:
        new_counts = defaultdict(int)
        for par, size in par_sizes.items():
            if size % 2 == 1:
                new_counts[par] += size
            else:
                new_counts[0] += size

        # For t > 1, we can compute recursively
        if t == 1:
            return max(new_counts.values())

        # After 2 seconds, each element with parity vector v will become the product of its group (size s)
        # The new parity vector will be:
        # - If s is odd and v is not 0, it stays v
        # - If s is odd and v is 0, it stays 0
        # - If s is even, it becomes 0 (since even * any = 0)

        # But wait, if we have elements with parity vector 0, multiplying them together keeps them 0
        # So elements with parity vector 0 will always stay 0

        # After 2 seconds:
        next_counts = defaultdict(int)
        for par, size in new_counts.items():
            if size % 2 == 1:
                next_counts[par] += size
            else:
                next_counts[0] += size

        # And so on... Actually, after 1 second, all groups with even size become parity 0
        # And parity 0 group is special - multiplying them together keeps them 0

        # So from time t >= 1, we have:
        # - Some elements with parity vectors v (non-zero)
        # - All elements become parity 0 after at most 1 second
        # - Parity 0 elements always stay 0

        # So for t >= 1, the beauty is the size of the largest group at time 1 (if any non-zero parity vectors exist)
        # Otherwise, all elements become 0, and they are all adjacent to each other (since 0/0 = 1 which is square)

        if len(new_counts) == 1 and 0 in new_counts:
            # All elements are parity 0
            return new_counts[0]

        # Otherwise, the beauty is the size of the largest group at time 1
        return max(new_counts.values())

    for w in queries:
        print(compute_beauty(w))
