def solve():
    # Read input
    n, m, k, s = map(int, input().split())

    # Read guitar configuration
    guitar = []
    for _ in range(n):
        row = list(map(int, input().split()))
        guitar.append(row)

    # Read song
    song = list(map(int, input().split()))

    # Create a mapping from note to list of (string, fret) positions
    note_positions = {}
    for i in range(n):
        for j in range(m):
            note = guitar[i][j]
            if note not in note_positions:
                note_positions[note] = []
            note_positions[note].append((i, j))

    # Function to check if we can play the song with maximum complexity at most max_complexity
    def can_play(max_complexity):
        # Use DP to determine if we can play the song
        # dp[i][(x, y)] = True if we can play up to position i ending at (x, y)
        dp = [{} for _ in range(s + 1)]

        # Base case: position 0 (before playing any note)
        for i in range(n):
            for j in range(m):
                dp[0][(i, j)] = True

        # Fill DP table
        for i in range(1, s + 1):
            current_note = song[i - 1]
            positions = note_positions.get(current_note, [])

            for (a, b) in positions:
                for (x, y) in dp[i - 1]:
                    # Check if transition from (x, y) to (a, b) has complexity <= max_complexity
                    if abs(x - a) + abs(y - b) <= max_complexity:
                        dp[i][(a, b)] = True

        return len(dp[s]) > 0

    # Binary search on the maximum complexity
    low = 0
    high = 2 * max(n, m)  # Maximum possible complexity is n + m

    # We need to find the maximum complexity that is achievable
    while low < high:
        mid = (low + high + 1) // 2
        if can_play(mid):
            low = mid
        else:
            high = mid - 1

    print(low)

