import sys

def is_balanced(s):
    """Check if a string has a correct cyclical shift"""
    n = len(s)
    if s.count('(') != s.count(')'):
        return 0

    # Check all possible rotations
    for k in range(n):
        balance = 0
        valid = True
        for i in range(n):
            char = s[(i + k) % n]
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                valid = False
                break
        if valid:
            return 1
    return 0

n = int(sys.stdin.readline())
original = sys.stdin.readline().strip()

max_beauty = 0
best_swap = (1, 1)

# Try all possible swaps
for i in range(n):
    for j in range(i, n):
        # Swap characters at positions i and j
        s = original[:i] + original[j] + original[i+1:j] + original[i] + original[j+1:]
        beauty = is_balanced(s)

        if beauty > max_beauty:
            max_beauty = beauty
            best_swap = (i+1, j+1)  # Convert to 1-indexed

print(max_beauty)
print(best_swap[0], best_swap[1])
