MOD = 1000000007

# Read input
import sys

def readints():
    return list(map(int, sys.stdin.readline().split()))

def char_to_num(c):
    if 'a' <= c <= 'z':
        return ord(c) - ord('a') + 1
    elif 'A' <= c <= 'Z':
        return ord(c) - ord('A') + 27
    else:
        return -1

def solve():
    # Read n, m, k
    line = sys.stdin.readline().split()
    while len(line) < 3:
        line += sys.stdin.readline().split()
    n, m, k = map(int, line)

    # Initialize adjacency matrix
    adj = [[1 if i == j else 0 for j in range(m)] for i in range(m)]

    # Read forbidden pairs
    for _ in range(k):
        line = sys.stdin.readline().strip()
        while len(line) < 2:
            line += sys.stdin.readline().strip()
        a, b = line[0], line[1]

        # Convert characters to nucleotide indices
        num_a = char_to_num(a)
        num_b = char_to_num(b)

        if num_a <= m and num_b <= m:
            # This pair is forbidden
            adj[num_a - 1][num_b - 1] = 0

    # Matrix exponentiation to compute adj^(n-1)
    def mat_mult(a, b):
        """Matrix multiplication with mod"""
        result = [[0] * len(b[0]) for _ in range(len(a))]
        for i in range(len(a)):
            for k in range(len(b)):
                if a[i][k] == 0:
                    continue
                for j in range(len(b[0])):
                    result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % MOD
        return result

    def mat_pow(mat, power):
        """Matrix exponentiation"""
        result = [[1 if i == j else 0 for j in range(len(mat))] for i in range(len(mat))]

        while power > 0:
            if power % 2 == 1:
                result = mat_mult(result, mat)
            mat = mat_mult(mat, mat)
            power //= 2

        return result

    # Compute adj^(n-1)
    if n == 0:
        print(0)
        return

    power = n - 1
    mat = mat_pow(adj, power)

    # Initial state: all nucleotides can be the start
    result = [0] * m
    for i in range(m):
        result[i] = sum(mat[i][j] for j in range(m)) % MOD

    print(sum(result) % MOD)

solve()
