import sys
import bisect

def generate_lucky_numbers():
    lucky = []
    from collections import deque
    queue = deque([4, 7])
    while queue:
        num = queue.popleft()
        if num <= 10**9:
            lucky.append(num)
            queue.append(num * 10 + 4)
            queue.append(num * 10 + 7)
    return sorted(lucky)

def count_lucky_in_range(a, b, lucky):
    left = bisect.bisect_left(lucky, a)
    right = bisect.bisect_right(lucky, b)
    return right - left

def solve():
    pl, pr, vl, vr, k = map(int, sys.stdin.readline().split())

    lucky = generate_lucky_numbers()

    total_pairs = (pr - pl + 1) * (vr - vl + 1)
    count = 0

    for p in range(pl, pr + 1):
        for v in range(vl, vr + 1):
            a = min(p, v)
            b = max(p, v)
            if count_lucky_in_range(a, b, lucky) == k:
                count += 1

    probability = count / total_pairs
    print(f"{probability:.15f}")

solve()
