import sys

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)
    if n == 0:
        print("No solution")
        return

    vowels = {'a','e','i','o','u','A','E','I','O','U'}

    # prefix sum of vowels
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i+1] = prefix[i] + (1 if s[i] in vowels else 0)

    # Find maximum length L such that some substring of length L is good
    # Binary search on L from 1 to n
    def is_good(L):
        if L == 0:
            return False
        for i in range(n - L + 1):
            cnt_v = prefix[i+L] - prefix[i]
            # Check if v <= 2 * (L - v)
            # v = cnt_v, c = L - v
            if cnt_v <= 2 * (L - cnt_v):
                return True
        return False

    low, high = 1, n
    max_len = 0
    while low <= high:
        mid = (low + high) // 2
        if is_good(mid):
            max_len = mid
            low = mid + 1
        else:
            high = mid - 1

    if max_len == 0:
        print("No solution")
        return

    # Count good substrings of length max_len
    cnt = 0
    for i in range(n - max_len + 1):
        cnt_v = prefix[i+max_len] - prefix[i]
        if cnt_v <= 2 * (max_len - cnt_v):
            cnt += 1

    print(f"{max_len} {cnt}")

if __name__ == "__main__":
    solve()
