def count_camels(n, t):
    """Count the number of valid camel polylines."""

    def backtrack(pos, prev, humps, valleys, seq):
        """Backtrack to build valid sequences."""
        if pos == n:
            # Check if we have exactly t humps and t-1 valleys
            if humps == t and valleys == t - 1:
                return 1
            return 0

        total = 0

        # Try each possible value for the current position
        for val in range(1, 5):
            if val == prev:
                continue  # No horizontal segments allowed

            # Check if this position could be a hump or valley
            if pos > 1 and pos < n:
                # Check if previous position was a hump or valley
                if seq[pos-2] < seq[pos-1] and seq[pos-1] > seq[pos]:
                    # This is a hump
                    total += backtrack(pos + 1, val, humps + 1, valleys, seq + [val])
                elif seq[pos-2] > seq[pos-1] and seq[pos-1] < seq[pos]:
                    # This is a valley
                    total += backtrack(pos + 1, val, humps, valleys + 1, seq + [val])
                else:
                    # This is a regular point
                    total += backtrack(pos + 1, val, humps, valleys, seq + [val])
            else:
                # First or last position, can't be hump or valley
                total += backtrack(pos + 1, val, humps, valleys, seq + [val])

        return total

    return backtrack(1, 0, 0, 0, [])

