def solve():
    n, m = map(int, input().split())
    grid = [input().strip() for _ in range(n)]

    # For each row, generate all valid patterns and their costs
    row_patterns = []
    for row in grid:
        costs = {}

        # Try all-one-color patterns
        for c in 'abcdefghijklmnopqrstuvwxyz':
            cost = sum(1 for ch in row if ch != c)
            costs[(c,)] = cost

        # Try two-color alternating patterns
        for c1 in 'abcdefghijklmnopqrstuvwxyz':
            for c2 in 'abcdefghijklmnopqrstuvwxyz':
                if c1 != c2:
                    # Pattern 1: c1, c2, c1, c2...
                    pattern = tuple([c1 if i % 2 == 0 else c2 for i in range(m)])
                    cost = sum(1 for i in range(m) if row[i] != pattern[i])
                    costs[pattern] = cost

        row_patterns.append(costs)

    # Use dynamic programming to find minimum cost
    # dp[i][pattern] = minimum cost to paint first i rows with pattern for row i
    dp = [{} for _ in range(n)]

    # Base case: first row
    for pattern, cost in row_patterns[0].items():
        dp[0][pattern] = cost

    # Fill DP table
    for i in range(1, n):
        for curr_pattern, curr_cost in row_patterns[i].items():
            # Find minimum previous state that is compatible
            min_prev_cost = float('inf')
            for prev_pattern, prev_cost in dp[i-1].items():
                # Check if patterns are compatible (no same color in same column)
                compatible = True
                for j in range(m):
                    if prev_pattern[j] == curr_pattern[j]:
                        compatible = False
                        break
                if compatible:
                    min_prev_cost = min(min_prev_cost, prev_cost)

            if min_prev_cost != float('inf'):
                dp[i][curr_pattern] = min_prev_cost + curr_cost

    # Find the minimum total cost
    min_total_cost = min(dp[n-1].values())

    # Reconstruct the solution
    pattern_sequence = []
    current_pattern = min(dp[n-1], key=lambda p: dp[n-1][p])
    pattern_sequence.append(current_pattern)

    for i in range(n-2, -1, -1):
        for prev_pattern, prev_cost in dp[i].items():
            if prev_pattern == current_pattern:
                continue
            compatible = True
            for j in range(m):
                if prev_pattern[j] == current_pattern[j]:
                    compatible = False
                    break
            if compatible:
                pattern_sequence.append(prev_pattern)
                current_pattern = prev_pattern
                break

    pattern_sequence.reverse()

    # Output the result
    print(min_total_cost)
    for pattern in pattern_sequence:
        print(''.join(pattern))

