# Read input
cake = []
h, w = map(int, input().split())
for _ in range(h):
    cake.append(input().strip())

# Simulate mouse path greedily
i, j = 0, 0
berries = 0

count_right = 0
for k in range(j+1, w):
    if cake[i][k] == '*':
        count_right += 1

count_down = 0
for k in range(i+1, h):
    if cake[k][j] == '*':
        count_down += 1

# Mouse chooses direction with more berries; if equal, it might choose randomly
# For suboptimal decisions, if equal, choose the direction with fewer total berries
if count_right > count_down:
    j += 1
    berries += (1 if cake[i][j] == '*' else 0)
elif count_down > count_right:
    i += 1
    berries += (1 if cake[i][j] == '*' else 0)
else:
    # If equal, choose the direction that leads to fewer berries (suboptimal)
    # Count berries if we go right
    count_right_total = count_right
    for k in range(j+1, w):
        if cake[i][k] == '*':
            count_right_total += 1

    # Count berries if we go down
    count_down_total = count_down
    for k in range(i+1, h):
        if cake[k][j] == '*':
            count_down_total += 1

    # Choose the direction with fewer berries
    if count_right_total < count_down_total:
        j += 1
        berries += (1 if cake[i][j] == '*' else 0)
    else:
        i += 1
        berries += (1 if cake[i][j] == '*' else 0)

# Output result
