            reverse_moves = [(0, 1), (1, 0)]  # D means (0, 1), R means (1, 0)
        elif record == "UR":
            # Forward: U or R → Backward: D or L
            reverse_moves = [(0, 1), (-1, 0)]
        elif record == "DL":
            # Forward: D or L → Backward: U or R
            reverse_moves = [(0, -1), (1, 0)]
        elif record == "DR":
            # Forward: D or R → Backward: U or L
            reverse_moves = [(0, -1), (-1, 0)]
        elif record == "ULDR":
            # Forward: U, L, D, or R → Backward: D, R, U, or L
            reverse_moves = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        else:
            raise ValueError("Invalid record")

        # Update possible positions
        new_positions = set()
        for pos in possible_positions:
            x, y = pos
            for dx, dy in reverse_moves:
                new_positions.add((x + dx, y + dy))

        possible_positions = new_positions

    print(len(possible_positions))

