import sys
from itertools import permutations

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    maze = []
    start = None
    end = None
    for i in range(n):
        line = next(it)
        maze.append(line)
        if 'S' in line:
            col = line.index('S')
            start = (i, col)
        if 'E' in line:
            col = line.index('E')
            end = (i, col)
    s = next(it)

    # directions: up, down, left, right
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    count = 0

    for perm in permutations(range(4)):
        dir_map = {}
        for digit, direction_idx in zip(range(4), perm):
            dir_map[digit] = dirs[direction_idx]
        curr = start
        success = False
        for c in s:
            d = int(c)
            dx, dy = dir_map[d]
            nx, ny = curr[0] + dx, curr[1] + dy
            if 0 <= nx < n and 0 <= ny < m and maze[nx][ny] != '#':
                curr = (nx, ny)
            else:
                break
            if maze[nx][ny] == 'E':
                success = True
                break
        if success:
            count += 1

    print(count)

if __name__ == "__main__":
    solve()
"}

