import sys
from collections import defaultdict

def count_occurrences(s):
    """Count occurrences of all substrings in s."""
    n = len(s)
    occurrences = defaultdict(int)

    # Count occurrences of each substring
    for i in range(n):
        for j in range(i, n):
            substr = s[i:j+1]
            occurrences[substr] += 1

    return occurrences

def is_good_substring(t, rules):
    """Check if substring t complies with all rules."""
    for p, l, r in rules:
        # Count occurrences of t in p
        cnt = 0
        n_p = len(p)
        for i in range(n_p):
            for j in range(i, n_p):
                if p[i:j+1] == t:
                    cnt += 1

        if not (l <= cnt <= r):
            return False
    return True

def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    s = data[0]
    n = int(data[1]) if len(data) > 1 else 0
    rules = []

    for i in range(2, 2 + n):
        if i >= len(data):
            break
        parts = data[i].split()
        if len(parts) < 3:
            continue
        p = parts[0]
        l = int(parts[1])
        r = int(parts[2])
        rules.append((p, l, r))

    # Count occurrences for all rules
    rule_occurrences = []
    for p, l, r in rules:
        occurrences = count_occurrences(p)
        rule_occurrences.append((p, l, r, occurrences))

    # Check all substrings of s
    good_substrings = set()
    n_s = len(s)

    for i in range(n_s):
        for j in range(i, n_s):
            t = s[i:j+1]
            good = True

            for p, l, r, occurrences in rule_occurrences:
                cnt = occurrences[t]
                if not (l <= cnt <= r):
                    good = False
                    break

            if good:
                good_substrings.add(t)

    print(len(good_substrings))

if __name__ == "__main__":
    main()
