n = int(input())
a = list(map(int, input().split()))

# Map each positive value to a list of indices (years)
value_to_years = {}
for i, val in enumerate(a):
    if val > 0:
        if val not in value_to_years:
            value_to_years[val] = []
        value_to_years[val].append(i + 1)  # years are 1-indexed

# Dynamic programming: dp[i] = length of longest perfect sequence ending with value i
# We also need to track the previous value in the sequence
prev = {}
lengths = {}

# Initialize for value 1
if 1 in value_to_years:
    lengths[1] = 1
    prev[1] = None

for val in sorted(value_to_years.keys()):
    if val == 1:
        continue

    # Check if we can extend a sequence ending with val-1
    if val - 1 in lengths:
        # We can extend the sequence
        new_length = lengths[val - 1] + 1
        if val not in lengths or new_length > lengths[val]:
            lengths[val] = new_length
            prev[val] = val - 1

# Find the maximum length
max_length = max(lengths.values()) if lengths else 0

if max_length == 0:
    print(0)
else:
    # Backtrack to find the sequence
    current_val = max(lengths.keys(), key=lambda k: lengths[k])
    sequence = []
    while current_val is not None:
        # Find the earliest year for this value (to maintain order)
        year = value_to_years[current_val][0]
        sequence.append(year)
        current_val = prev[current_val]

    # Reverse to get the correct order
    sequence.reverse()

    print(len(sequence))
    print(' '.join(map(str, sequence)))
