def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # dp[i][j] = max points for subarray a[i..j] (0-indexed)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):  # length of subarray
        for i in range(n - length + 1):
            j = i + length - 1

            # Try removing each element k in subarray [i..j]
            max_points = 0
            for k in range(i, j + 1):
                points = 0

                # If k is not the first element, get points from left neighbor
                if k > i:
                    points = a[k - 1]

                # If k is not the last element, get points from right neighbor
                if k < j:
                    points = a[k + 1]

                # Actually, we should get min(left, right) if both exist, otherwise just the existing neighbor
                if k > i and k < j:
                    points = min(a[k - 1], a[k + 1])
                elif k > i:
                    points = a[k - 1]
                elif k < j:
                    points = a[k + 1]
                else:
                    points = 0

                max_points = max(max_points, points + dp[i][k - 1] + dp[k + 1][j])

            dp[i][j] = max_points

    print(dp[0][n - 1])

if __name__ == '__main__':
    solve()
"}

