    # Move decimal point b places to the right
    integer_part = a + d[:b-1]
    decimal_part = d[b-1:]

    # Remove trailing zeros from decimal part
    decimal_part = decimal_part.rstrip('0')

    if decimal_part:
        print(f"{integer_part}.{decimal_part}")
