def count_sequences(n, t):
    """Count valid camel sequences with n vertices and t humps."""

    # Memoization cache
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, prev, humps, valleys, started):
        """Dynamic programming function:
        pos: current position (1-indexed)
        prev: previous y-value
        humps: number of humps so far
        valleys: number of valleys so far
        started: whether we've started the sequence yet"""

        # Base case: we've completed the sequence
        if pos > n:
            # Check if we have exactly t humps and t-1 valleys
            return 1 if humps == t and valleys == t - 1 else 0

        total = 0

        # Try all possible next values
        for next_val in range(1, 5):
            if next_val == prev:
                continue  # No horizontal segment

            # Check if we've started the sequence
            if not started:
                # We're starting, just move to next position
                total += dp(pos + 1, next_val, humps, valleys, True)
            else:
                # Check if this forms a hump, valley, or neither
                # Check if we have at least 3 positions to form a triplet
                if pos >= 3:
                    prev_prev = prev
                    # Check if (prev_prev, prev, next_val) forms a hump or valley
                    if prev_prev < prev and prev > next_val:
                        # Hump
                        total += dp(pos + 1, next_val, humps + 1, valleys, True)
                    elif prev_prev > prev and prev < next_val:
                        # Valley
                        total += dp(pos + 1, next_val, humps, valleys + 1, True)
                    else:
                        # Neither
                        total += dp(pos + 1, next_val, humps, valleys, True)
                else:
                    # Not enough positions to form a hump/valley yet
                    total += dp(pos + 1, next_val, humps, valleys, True)

        return total

    # Start at position 1, no previous value, 0 humps, 0 valleys, not started
    return dp(1, 0, 0, 0, False)

n, t = map(int, input().split())
print(count_sequences(n, t))
