                total += dp(pos + 1, next_val, humps, valleys, True)
            else:
                # Check if this forms a hump, valley, or neither
                # Check if we have at least 3 positions to form a triplet
                if pos >= 3:
                    prev_prev = prev
                    # Check if (prev_prev, prev, next_val) forms a hump or valley
                    if prev_prev < prev and prev > next_val:
                        # Hump
                        total += dp(pos + 1, next_val, humps + 1, valleys, True)
                    elif prev_prev > prev and prev < next_val:
                        # Valley
                        total += dp(pos + 1, next_val, humps, valleys + 1, True)
                    else:
                        # Neither
                        total += dp(pos + 1, next_val, humps, valleys, True)
                else:
                    # Not enough positions to form a hump/valley yet
                    total += dp(pos + 1, next_val, humps, valleys, True)

        return total

    # Start at position 1, no previous value, 0 humps, 0 valleys, not started
    return dp(1, 0, 0, 0, False)

