    n = len(friends)
    if n == 0:
        return 0.0

    # Probability of exactly one success
    prob = 0.0

    # Try all subsets of friends
    for mask in range(1, 1 << n):
        # Count number of friends in this subset
        k = bin(mask).count('1')

        # If we ask k friends, calculate the probability of exactly one success
        if k == 0:
            continue

        # Calculate the probability of exactly one success
        total = 0.0
        for i in range(n):
            # Check if friend i is in the subset
            if mask & (1 << i):
                # Calculate the probability that friend i succeeds and others fail
                p = friends[i]
                for j in range(n):
