def is_good(vowels, length):
    return vowels <= 2 * (length - vowels)

# Check if v <= 2c where v = vowels, c = consonants
# v <= 2(length - v) => v <= 2length - 2v => 3v <= 2length => v <= (2/3) * length

s = input().strip()
max_len = 0
count = 0

# We'll use a sliding window approach
left = 0
vowel_count = 0

for right in range(len(s)):
    # Expand window to the right
    if s[right] in 'aeiouAEIOU':
        vowel_count += 1

    # Shrink window from the left if too many vowels
    while vowel_count > 2 * (right - left + 1) - vowel_count:
        # We need to remove vowels from the left
        if s[left] in 'aeiouAEIOU':
            vowel_count -= 1
        left += 1

    # Now the window [left, right] is good
    current_len = right - left + 1

    if current_len > max_len:
        max_len = current_len
        count = 1
    elif current_len == max_len:
        count += 1

if max_len == 0:
    print("No solution")
else:
    print(max_len, count)
