n, k = map(int, input().split())

# If k = 1, it's impossible
if k == 1:
    print(-1)
    exit()

# If k > n-1, impossible
if k > n - 1:
    print(-1)
    exit()

# If k > n/2, it's impossible because then white diameter would be < k
# (white diameter = k, red diameter = n-1-k < k, so min = n-1-k < k)
if k > n / 2:
    print(-1)
    exit()

# Create a white path of length k (diameter k)
white_edges = []
for i in range(k):
    white_edges.append((i + 1, i + 2))  # Path: 1-2-3-...-(k+1)

# All other edges are red
red_edges = []
for u in range(1, n + 1):
    for v in range(u + 1, n + 1):
        if (u, v) not in white_edges and (v, u) not in white_edges:
            red_edges.append((u, v))

# Output red edges
print(len(red_edges))
for a, b in red_edges:
    print(a, b)
