# Find the smallest x such that x divides n and the matrix can be partitioned into x-sized blocks with symmetry
# The largest possible x is n / 2^k for some k. We want the largest x that divides n.
# Try all divisors of n to find the largest valid x.

# Find all divisors of n
def get_divisors(n):
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

divisors = get_divisors(n)

# Try each divisor in decreasing order (largest first)
for x in divisors:
    if n % x != 0:
        continue

    # Check if the matrix can be partitioned into x-sized blocks with symmetry
    # The matrix should be symmetric around the middle line
    # For each row i in 0..x-1, row i should equal row n - 1 - i
    valid = True
    for i in range(x):
        if a[i] != a[n - 1 - i]:
            valid = False
            break

    if valid:
        print(x)
        exit()

print(n)  # If no divisor works, the answer is n itself (no mirroring)
