    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    result = 0

    # Consider each bit position from 0 to 23 (since 10^7 < 2^24)
    for bit in range(24):
        count = 0
        for num in a:
            if (num >> bit) & 1:
                count += 1

        # Number of pairs with exactly one bit set
        pairs_with_one_bit_set = count * (n - count)

        # If odd, set this bit in the result
        if pairs_with_one_bit_set % 2 == 1:
            result |= (1 << bit)

    print(result)

if __name__ == "__main__":
    solve()
