    """Generate all 4 rotations of a piece of size x×y"""
    rotations = []

    # Original piece
    rotations.append((x, y, [row[:] for row in piece]))

    # Rotate 90 degrees clockwise: new size is y×x
    rotated_90 = []
    for col in reversed(range(y)):
        new_row = [piece[row][col] for row in range(x)]
        rotated_90.append(new_row)
    rotations.append((y, x, rotated_90))

    # Rotate 180 degrees: new size is x×y
    rotated_180 = []
    for row in reversed(range(x)):
        new_row = [piece[row][col] for col in range(y)]
        rotated_180.append(new_row)
    rotations.append((x, y, rotated_180))

    # Rotate 270 degrees clockwise: new size is y×x
    rotated_270 = []
    for col in range(y):
        new_row = [piece[row][col] for row in reversed(range(x))]
        rotated_270.append(new_row)
    rotations.append((y, x, rotated_270))

    return rotations

