    """Check if a puzzle with piece size X×Y is good"""
    num_pieces_x = A // X
    num_pieces_y = B // Y
    pieces = []  # Store all pieces

    for i in range(num_pieces_x):
        for j in range(num_pieces_y):
            # Extract piece
            piece = []
            for row in range(X):
                piece_row = []
                for col in range(Y):
                    piece_row.append(picture[i*X + row][j*Y + col])
