def count_lucky_numbers(n):
    """Count how many lucky numbers are <= n"""
    count = 0
    # Generate all lucky numbers up to n
    lucky = []
    for length in range(1, 11):  # max 10 digits
        for digits in range(2 ** length):
            # Generate binary number and convert to lucky number
            # 0 represents 4, 1 represents 7
            num = 0
            for bit in range(length):
                if digits & (1 << bit):
                    num = num * 10 + 7
                else:
                    num = num * 10 + 4
            if num <= n:
                lucky.append(num)
    return lucky

def solve():
    pl, pr, vl, vr, k = map(int, input().split())

    # Generate all lucky numbers up to 10^9
    lucky = count_lucky_numbers(10**9)

    # Count how many pairs (p, v) give exactly k lucky numbers in their interval
    total_pairs = (pr - pl + 1) * (vr - vl + 1)
    valid_pairs = 0

    # Brute force - this might not work for large ranges
    for p in range(pl, pr + 1):
        for v in range(vl, vr + 1):
            left = min(p, v)
            right = max(p, v)
            # Count lucky numbers in [left, right]
            count = 0
            for num in lucky:
                if left <= num <= right:
                    count += 1
            if count == k:
                valid_pairs += 1

    probability = valid_pairs / total_pairs
    print(f"{probability:.15f}")

solve()
