import sys

def square_free(n):
    result = n
    i = 2
    while i * i <= result:
        if result % i == 0:
            count = 0
            while result % i == 0:
                result //= i
                count += 1
            if count % 2 == 1:
                result *= i
        i += 1
    return result

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]
        q = int(next(it))
        queries = [int(next(it)) for _ in range(q)]

        # Compute square-free parts
        square_free_parts = [square_free(x) for x in a]

        # Count frequency of each square-free part
        count = {}
        for s in square_free_parts:
            count[s] = count.get(s, 0) + 1

        # Initial beauty
        max_initial = max(count.values())

        # For w >= 1, after 1 second:
        # - If count[s] is odd, all elements with square-free part s will become s
        # - If count[s] is even, all elements with square-free part s will become 1
        # Then adjacency is based on these new values

        # Compute adjacency after 1 second
        new_square_free_parts = []
        for s in square_free_parts:
            if count[s] % 2 == 1:
                new_square_free_parts.append(s)
            else:
                new_square_free_parts.append(1)

        # Compute count after 1 second
        new_count = {}
        for s in new_square_free_parts:
            new_count[s] = new_count.get(s, 0) + 1

        max_after_1 = max(new_count.values())

        # For w == 0, answer is max_initial
        # For w >= 1, answer is max_after_1

        out_lines.append(str(max_initial))

        for w in queries:
            if w == 0:
                out_lines.append(str(max_initial))
            else:
                out_lines.append(str(max_after_1))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

