        for s in square_free_parts:
            if count[s] % 2 == 1:
                new_square_free_parts.append(s)
            else:
                new_square_free_parts.append(1)

        # Compute count after 1 second
        new_count = {}
        for s in new_square_free_parts:
            new_count[s] = new_count.get(s, 0) + 1

        max_after_1 = max(new_count.values())

        # For w == 0, answer is max_initial
        # For w >= 1, answer is max_after_1

        out_lines.append(str(max_initial))

        for w in queries:
            if w == 0:
                out_lines.append(str(max_initial))
            else:
                out_lines.append(str(max_after_1))

    sys.stdout.write("\n".join(out_lines))

