    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        r_line = next(it).strip()
        r, c = map(int, r_line.split())
        grid = []
        for _ in range(r):
            line = next(it).strip()
            grid.append(line)

        # Find all 'A' positions
        a_positions = []
        for i in range(r):
            for j in range(c):
                if grid[i][j] == 'A':
                    a_positions.append((i, j))

        if not a_positions:
            print("MORTAL")
            continue

        # Check if we can convert the entire grid in one operation
        has_row_a = [False] * r
        has_col_a = [False] * c

        for i, j in a_positions:
            has_row_a[i] = True
            has_col_a[j] = True

        if all(has_row_a) and all(has_col_a):
            print(1)
        else:
            print(2)

solve()
