import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        r_line = next(it).strip()
        r, c = map(int, r_line.split())
        grid = []
        for _ in range(r):
            line = next(it).strip()
            grid.append(line)

        # Find all 'A' positions
        a_positions = []
        for i in range(r):
            for j in range(c):
                if grid[i][j] == 'A':
                    a_positions.append((i, j))

        if not a_positions:
            print("MORTAL")
            continue

        # Find all 'P' positions
        p_positions = []
        for i in range(r):
            for j in range(c):
                if grid[i][j] == 'P':
                    p_positions.append((i, j))

        # Check if all 'P' are in a single row
        all_in_row = None
        for i, j in p_positions:
            if all_in_row is None:
                all_in_row = i
            elif i != all_in_row:
                break
        else:
            # All 'P' in the same row
            print(1)
            continue

        # Check if all 'P' are in a single column
        all_in_col = None
        for i, j in p_positions:
            if all_in_col is None:
                all_in_col = j
            elif j != all_in_col:
                break
        else:
            # All 'P' in the same column
            print(1)
            continue

        # Now check if we need 2 or 4 operations
        # Count how many rows and columns have no 'A'
        has_row_a = [False] * r
        has_col_a = [False] * c

        for i, j in a_positions:
            has_row_a[i] = True
            has_col_a[j] = True

        missing_rows = sum(1 for i in range(r) if not has_row_a[i])
        missing_cols = sum(1 for j in range(c) if not has_col_a[j])

        # If there's at least one 'A' in every row or every column, answer is 2
        if all(has_row_a) or all(has_col_a):
            print(2)
