import sys

def is_balanced(s):
    """Check if a string is balanced (equal number of '(' and ')')"""
    return s.count('(') == s.count(')')

def min_prefix_sum(s):
    """Check if the minimum prefix sum is non-negative"""
    balance = 0
    min_balance = 0
    for c in s:
        if c == '(':
            balance += 1
        else:
            balance -= 1
        min_balance = min(min_balance, balance)
    return min_balance >= 0

def count_valid_cyclical_shifts(s):
    """Count how many cyclical shifts form a correct bracket sequence"""
    n = len(s)
    if not is_balanced(s):
        return 0

    # Check all cyclical shifts
    count = 0
    for i in range(n):
        # Cyclical shift by i
        shifted = s[i:] + s[:i]
        if min_prefix_sum(shifted):
            count += 1
    return count

def solve():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    # Try all possible swaps
    max_beauty = 0
    best_l, best_r = 1, 1

    # Try swapping i and j for all 0 <= i, j < n
    for i in range(n):
        for j in range(n):
            # Swap characters at positions i and j
            new_s = s[:i] + s[j] + s[i+1:j] + s[i] + s[j+1:]
            beauty = count_valid_cyclical_shifts(new_s)

            if beauty > max_beauty:
                max_beauty = beauty
                best_l, best_r = i + 1, j + 1

    print(max_beauty)
    print(best_l, best_r)

if __name__ == "__main__":
    solve()
