def find_sequence(n):
    """Find a sequence of digits {1, 3, 7} with exactly n subsequences equal to 1337"""

    # Try all factorizations of n into three integers a, b, c
    # such that a * b * c = n and find one with minimum length
    min_len = float('inf')
    best = None

    # Try a from 1 to cube root of n
    for a in range(1, int(n ** (1/3)) + 1):
        if n % a != 0:
            continue

        # Try b from 1 to sqrt(n/a)
        for b in range(1, int((n // a) ** 0.5) + 1):
            if (n // a) % b != 0:
                continue

            c = (n // a) // b

            # Check if a * b * c = n
            if a * b * c == n:
                length = a + b + c
                if length < min_len:
                    min_len = length
                    best = (a, b, c)

    # If no factorization found, try with a=1 and try different b
    if best is None:
        for b in range(1, int(n ** 0.5) + 1):
            if n % b != 0:
                continue
            c = n // b
            if b * c == n:
                length = 1 + b + c
                if length < min_len:
                    min_len = length
                    best = (1, b, c)

    # If still no factorization found, use a=1, b=1, c=n
    if best is None:
        best = (1, 1, n)

    # Construct the sequence: a '1's, b '3's, c '7's
    result = '1' * best[0] + '3' * best[1] + '7' * best[2]
    return result

# Read input and output results
t = int(input())
for _ in range(t):
    n = int(input())
    print(find_sequence(n))
