def is_vowel(c):
    return c in {'a', 'e', 'i', 'o', 'u'}

s = input().strip()
N = len(s)

# Two-pointer to find max length L
max_len = 0
count_max = 0
i = 0
prefix_v = [0] * (N + 1)
for j in range(N):
    prefix_v[j+1] = prefix_v[j] + (1 if is_vowel(s[j]) else 0)

# Two-pointer for max length
left = 0
for right in range(N):
    # Maintain condition: v <= floor(2/3 (right - left))
    while left <= right:
        L = right - left
        v = prefix_v[right+1] - prefix_v[left]
        if v > 2 * L // 3:
            left += 1
        else:
            break
    current_length = right - left + 1
    if current_length > max_len:
        max_len = current_length
        count_max = 1
    elif current_length == max_len:
        count_max += 1

# Also check if max_len > 0, then count all substrings of length max_len that are good
if max_len == 0:
    print("No solution")
else:
    # Count substrings of length max_len
    cnt = 0
    for i in range(N - max_len + 1):
        j = i + max_len
        v = prefix_v[j] - prefix_v[i]
        if v <= 2 * max_len // 3:
            cnt += 1
    print(f"{max_len} {cnt}")
