def count_distinct_sums(n):
    if n == 0:
        return 1

    # Using dynamic programming for small n
    dp = [set() for _ in range(n + 1)]

    # Base case: 0 digits gives sum 0
    dp[0].add(0)

    # Build up solution
    for i in range(1, n + 1):
        for s in dp[i-1]:
            dp[i].add(s + 1)  # Add digit I
