def solve():
    n = int(input())
    movements = [input().strip() for _ in range(n)]

    # Set of possible positions after each step (working backwards)
    positions = {(0, 0)}

    # Process movements in reverse order
    for i in range(n - 1, -1, -1):
        movement = movements[i]

        # Get all possible directions for this movement
        if movement == "UL":
            directions = [(0, 1), (1, 0)]  # U means (0, 1), L means (1, 0)
        elif movement == "UR":
            directions = [(0, 1), (-1, 0)]  # U means (0, 1), R means (-1, 0)
        elif movement == "DL":
            directions = [(0, -1), (1, 0)]  # D means (0, -1), L means (1, 0)
        elif movement == "DR":
            directions = [(0, -1), (-1, 0)]  # D means (0, -1), R means (-1, 0)
        elif movement == "ULDR":
            directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # U, L, D, R
        else:
            raise ValueError(f"Unknown movement: {movement}")

