def count_occurrences(t, p):
    """Count the number of occurrences of substring t in string p"""
    return p.count(t)

def is_good(t, rules):
    """Check if substring t complies with all rules"""
    for p, l, r in rules:
        count = count_occurrences(t, p)
        if not (l <= count <= r):
            return False
    return True

s = input().strip()
