rules = []
for _ in range(n):
    parts = input().split()
    p = parts[0]
    l = int(parts[1])
    r = int(parts[2])
    rules.append((p, l, r))

# Generate all distinct substrings of s
distinct_substrings = set()
length = len(s)
for i in range(length):
    for j in range(i + 1, length + 1):
        substring = s[i:j]
        distinct_substrings.add(substring)

# Count good substrings
good_count = 0
for t in distinct_substrings:
    if is_good(t, rules):
        good_count += 1

